// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the scroll target, normalized to 60fps. */
const OPEN_LERP = 0.14;

/**
 * Drives `--bloom-open` (0 → 1) on the referenced element based on how far
 * the viewport has scrolled through the element's own height — the pinned
 * "the bloom" section. As you scroll the pinned flower stays put while
 * `--bloom-open` rises from 0 (a closed bud, petals scaled to 0.42 and
 * rotated -8°) to 1 (fully open, petals at scale 1, rotation 0°). The
 * section's height in CSS is taller than the viewport on purpose (a sticky
 * inner), so the progress maps cleanly onto a few screens of scroll.
 *
 * The CSS fallback is `var(--bloom-open, 1)` — fully open — so without
 * JavaScript, and under reduced motion (where this hook does nothing), the
 * signature flower simply stands open. The lerp makes it scrubbable without
 * jitter: scrolling fast opens fast, scrolling slow opens slow, and
 * scrolling back up closes the flower again.
 *
 * The scroll handler is passive and only writes to a CSS custom property
 * (no layout work); the rAF loop runs only while the section is on screen
 * and the tab is visible.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;

    el.style.setProperty("--bloom-open", "0");

    let raf = 0;
    let running = false;
    let inView = true;
    let value = 0;
    let last = 0;
    let target = 0;

    const computeTarget = () => {
      const rect = el.getBoundingClientRect();
      // Progress is how far the section's top has traveled from "just
      // entered at the bottom" to "its content has scrolled past". We pin
      // via position: sticky in CSS, so the visible flower stays fixed
      // while this number climbs.
      const total = rect.height - window.innerHeight;
      if (total <= 0) {
        target = 1;
        return;
      }
      // When the section top is at or above the viewport top, progress
      // starts; it completes when the section's bottom reaches the fold.
      const traveled = Math.min(Math.max(-rect.top, 0), total);
      target = traveled / total;
    };

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const next = value + (target - value) * OPEN_LERP * (dt / 16.7);
      if (Math.abs(next - value) < 0.0002) return;
      value = next;
      el.style.setProperty("--bloom-open", value.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      computeTarget();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onScroll = () => {
      if (inView && !document.hidden) computeTarget();
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      // hand the element back to the CSS fallback (fully open)
      el.style.removeProperty("--bloom-open");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useScrollProgress } from "./hooks/useScrollProgress";
import { usePointerParallax } from "./hooks/usePointerParallax";

/**
 * FOREST — 숲, 깊은 수관의 은신처. Organic-nature entry where the canopy
 * darkens as you scroll deeper (scroll-scrub-pinned via --forest-depth),
 * dappled light filters through feTurbulence leaves (feturbulence-texture),
 * and the canopy layers drift toward the pointer (pointer-parallax).
 */
export default function ForestPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const depthRef = useScrollProgress<HTMLDivElement>(reduced);
  const canopyRef = usePointerParallax<HTMLDivElement>(reduced);

  useEffect(() => {
    rootRef.current?.classList.add("forest-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "forest" }, "*");
  }, []);

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSansKR.variable} forest-root`}>
      <div ref={revealRef} className="forest-doc">
        {/* pointer-parallax canopy layers — a generated painterly canopy photo
            (far layer) behind the CSS leaf shapes (mid + near), so the
            retreat reads as a real forest, not a gradient. */}
        <div ref={canopyRef} className="forest-canopy" aria-hidden="true">
          <img
            className="forest-canopy__photo"
            src="/media/forest/canopy.avif"
            alt=""
            draggable="false"
          />
          <div className="forest-canopy__layer forest-canopy__layer--mid" />
          <div className="forest-canopy__layer forest-canopy__layer--near" />
        </div>

        <header className="forest-hero" data-reveal="">
          <p className="forest-kicker"><span lang="ko">깊은 수관의 은신처</span> · DEEP CANOPY RETREAT</p>
          <h1 className="forest-title">
            FOREST <span lang="ko">숲</span>
          </h1>
          <p className="forest-sub"><span lang="ko">내려갈수록 수관이 어두워진다.</span> The canopy darkens as you descend.</p>
        </header>

        {/* scroll-scrub-pinned: the descent */}
        <section ref={depthRef} className="forest-descent" data-reveal="">
          <div className="forest-descent__inner">
            <p className="forest-descent__word" lang="ko">빛이 줄어든다</p>
            <p className="forest-descent__word" lang="ko">이끼가 늘어난다</p>
            <p className="forest-descent__word" lang="ko">숨이 깊어진다</p>
            <p className="forest-descent__en"><em>Light thins · moss thickens · breath deepens</em></p>
          </div>
        </section>

        {/* feturbulence-texture: dappled leaf overlay */}
        <svg className="forest-dapple" aria-hidden="true" focusable="false">
          <filter id="forest-leaf-f">
            <feTurbulence type="fractalNoise" baseFrequency="0.02 0.04" numOctaves="3" seed="7" stitchTiles="stitch" />
            <feColorMatrix type="matrix" values="0 0 0 0 0.08  0 0 0 0 0.12  0 0 0 0 0.04  0 0 0 0.12 0" />
          </filter>
          <rect width="100%" height="100%" filter="url(#forest-leaf-f)" />
        </svg>

        <footer className="forest-foot" data-reveal="">
          <p>© 2026 FOREST · <span lang="ko">숲</span> · MIT</p>
          <p><span lang="ko">깊이 숨쉬어라 — 숲은 기다린다.</span> breathe deep — the forest waits.</p>
        </footer>
      </div>
    </div>
  );
}

/* FOREST 숲 — deep canopy retreat · organic-nature
   canopy-dark / green / dapple · scroll-darkens, leaves filter light */

.forest-root {
  --forest-light: #f0fdf4;
  --forest-mid: #15803d;
  --forest-deep: #0a1f0a;
  --forest-dapple: #86efac;
  --forest-ink: #052e16;

  position: relative;
  min-height: 100vh;
  background: var(--forest-light);
  color: var(--forest-ink);
  font-family: "Inter", "Noto Sans KR", sans-serif;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.8;
  overflow-x: hidden;
  overflow-x: clip;
}

.forest-root :lang(ko) { font-family: "Noto Sans KR", sans-serif; }
.forest-root ::selection { background: var(--forest-mid); color: #fff; }
.forest-root :focus-visible { outline: 2px solid var(--forest-mid); outline-offset: 4px; }

.forest-js [data-reveal] {
  opacity: 0; transform: translateY(24px);
  transition: opacity 900ms cubic-bezier(0.16,1,0.3,1), transform 900ms cubic-bezier(0.16,1,0.3,1);
}
.forest-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .forest-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.forest-doc { position: relative; z-index: 1; }

/* pointer-parallax canopy layers — SVG leaf shapes at different depths */
.forest-canopy {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  transition: transform 800ms cubic-bezier(0.16,1,0.3,1);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .forest-canopy { transform: none !important; transition: none; }
}
.forest-canopy__layer {
  position: absolute;
  inset: -10%;
  background-repeat: repeat;
  opacity: 0.15;
}
/* The generated painterly canopy photo — the far layer, a real forest seen
   from below. Darkened and tinted to sit behind the CSS leaf shapes.        */
.forest-canopy__photo {
  position: absolute;
  inset: -5% -5% -15% -5%;
  width: 110%;
  height: 120%;
  object-fit: cover;
  object-position: center top;
  opacity: 0.42;
  filter: saturate(0.9) brightness(0.78) contrast(1.05);
  transform: translateX(calc(var(--drm-px, 0) * -10px));
}
.forest-canopy__layer--far {
  display: none;
}
.forest-canopy__layer--mid {
  background: radial-gradient(ellipse 120px 60px at 30% 10%, var(--forest-mid) 35%, transparent 65%),
              radial-gradient(ellipse 100px 50px at 80% 30%, var(--forest-mid) 35%, transparent 65%);
  background-size: 300px 200px;
  opacity: 0.12;
}
.forest-canopy__layer--near {
  background: radial-gradient(ellipse 200px 100px at 50% 0%, var(--forest-ink) 40%, transparent 60%);
  opacity: 0.18;
}

/* Hero */
.forest-hero {
  position: relative;
  z-index: 2;
  padding: clamp(80px, 18vh, 160px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 80px);
  text-align: center;
}
.forest-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--forest-mid);
  margin: 0 0 30px;
}
.forest-title {
  font-weight: 700;
  font-size: clamp(3.5rem, 12vw, 8rem);
  line-height: 0.9;
  margin: 0 0 20px;
}
.forest-title :lang(ko) { font-size: 0.4em; color: var(--forest-mid); display: block; margin-top: 8px; }
.forest-sub { color: var(--forest-ink); opacity: 0.7; margin: 0; }

/* scroll-scrub-pinned: the descent — darkens with --forest-scrub */
.forest-descent {
  position: relative;
  z-index: 2;
  min-height: 200vh;
  background: var(--forest-light);
}
.forest-descent__inner {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  /* darken with scroll progress */
  background: color-mix(in srgb, var(--forest-deep) calc(var(--forest-scrub, 0) * 80%), transparent);
  color: color-mix(in srgb, var(--forest-light) calc(var(--forest-scrub, 0) * 100%), var(--forest-ink));
  transition: background 200ms, color 200ms;
}
.forest-descent__word {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 600;
  margin: 0 0 20px;
  opacity: calc(0.4 + var(--forest-scrub, 0) * 0.6);
}
.forest-descent__en {
  font-size: 0.95rem;
  opacity: 0.5;
  margin: 16px 0 0;
}
.forest-descent__en em { font-style: italic; }

/* feturbulence-texture: dappled leaf overlay */
.forest-dapple {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 3;
  pointer-events: none;
  mix-blend-mode: multiply;
  opacity: 0.5;
}

/* Footer */
.forest-foot {
  position: relative;
  z-index: 2;
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  background: var(--forest-deep);
  color: var(--forest-light);
  font-size: 0.82rem;
}
.forest-foot p { margin: 0 0 6px; }
